-- Local continuation experiment only. Ordinary DML cannot enable this fence.
-- External old writers/provider operations still require the separate #296 gate.
-- The receipt exists and remains blocked even if a later migration is partial.
CREATE TABLE IF NOT EXISTS serial_pilot_final_receipts(
 operation_token TEXT PRIMARY KEY,epoch_id TEXT NOT NULL UNIQUE,spreadsheet_id TEXT NOT NULL,job_id TEXT NOT NULL,
 nonce TEXT NOT NULL,worker_version TEXT NOT NULL,source_revision INTEGER NOT NULL,source_digest TEXT NOT NULL,
 provider_algorithm TEXT NOT NULL CHECK(provider_algorithm='SHA256_MALIPANG_PROJECTION_SNAPSHOT_V1'),
 provider_digest TEXT NOT NULL CHECK(length(provider_digest)=64 AND provider_digest NOT GLOB '*[^0-9a-f]*'),
 notice_algorithm TEXT NOT NULL CHECK(notice_algorithm='SHA256_MALIPANG_NOTICE_POSTIMAGE_V1'),
 notice_digest TEXT NOT NULL CHECK(length(notice_digest)=64 AND notice_digest NOT GLOB '*[^0-9a-f]*'),
 provider_observed_at TEXT NOT NULL,notice_observed_at TEXT NOT NULL,recorded_at TEXT NOT NULL
);
CREATE TRIGGER IF NOT EXISTS serial_final_receipt_not_ready BEFORE INSERT ON serial_pilot_final_receipts BEGIN SELECT RAISE(ABORT,'final receipt not ready'); END;
CREATE TRIGGER IF NOT EXISTS serial_final_receipt_no_replace BEFORE INSERT ON serial_pilot_final_receipts WHEN EXISTS(SELECT 1 FROM serial_pilot_final_receipts r WHERE r.operation_token=NEW.operation_token OR r.epoch_id=NEW.epoch_id OR r.rowid=NEW.rowid) BEGIN SELECT RAISE(ABORT,'final receipt retained'); END;
CREATE TRIGGER IF NOT EXISTS serial_final_receipt_no_update BEFORE UPDATE ON serial_pilot_final_receipts BEGIN SELECT RAISE(ABORT,'final receipt immutable'); END;
CREATE TRIGGER IF NOT EXISTS serial_final_receipt_no_delete BEFORE DELETE ON serial_pilot_final_receipts BEGIN SELECT RAISE(ABORT,'final receipt retained'); END;

-- Present from 0074 so a partial migration cannot expose an unguarded final
-- authorization. 0077 will replace only the unimplemented guard locally;
-- the independent not-ready barrier remains closed until a separate gate.
CREATE TABLE IF NOT EXISTS serial_pilot_final_completions(
 operation_token TEXT PRIMARY KEY,epoch_id TEXT NOT NULL UNIQUE,spreadsheet_id TEXT NOT NULL,job_id TEXT NOT NULL,nonce TEXT NOT NULL,worker_version TEXT NOT NULL,
 daily_id INTEGER NOT NULL,daily_name TEXT NOT NULL,raw_id INTEGER NOT NULL,raw_name TEXT NOT NULL,detail_id INTEGER NOT NULL,detail_name TEXT NOT NULL,
 provider_digest TEXT NOT NULL,notice_digest TEXT NOT NULL,provider_observed_at TEXT NOT NULL,notice_observed_at TEXT NOT NULL,completed_at TEXT NOT NULL
);
CREATE TRIGGER IF NOT EXISTS serial_final_completion_not_ready BEFORE INSERT ON serial_pilot_final_completions BEGIN SELECT RAISE(ABORT,'final completion not ready'); END;
CREATE TRIGGER IF NOT EXISTS serial_final_completion_unimplemented BEFORE INSERT ON serial_pilot_final_completions BEGIN SELECT RAISE(ABORT,'final completion not implemented'); END;
CREATE TRIGGER IF NOT EXISTS serial_final_completion_no_replace BEFORE INSERT ON serial_pilot_final_completions WHEN EXISTS(SELECT 1 FROM serial_pilot_final_completions c WHERE c.operation_token=NEW.operation_token OR c.epoch_id=NEW.epoch_id OR c.rowid=NEW.rowid) BEGIN SELECT RAISE(ABORT,'final completion retained'); END;
CREATE TRIGGER IF NOT EXISTS serial_final_completion_no_update BEFORE UPDATE ON serial_pilot_final_completions BEGIN SELECT RAISE(ABORT,'final completion immutable'); END;
CREATE TRIGGER IF NOT EXISTS serial_final_completion_no_delete BEFORE DELETE ON serial_pilot_final_completions BEGIN SELECT RAISE(ABORT,'final completion retained'); END;
CREATE TABLE IF NOT EXISTS serial_pilot_continuation_sessions(
 epoch_id TEXT PRIMARY KEY, spreadsheet_id TEXT NOT NULL, job_id TEXT NOT NULL, nonce TEXT NOT NULL UNIQUE,
 fence_digest TEXT NOT NULL, fence_generation INTEGER NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS serial_pilot_continuation_completions(
 epoch_id TEXT PRIMARY KEY, completed_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS serial_pilot_continuation_permits(
 operation_token TEXT PRIMARY KEY, epoch_id TEXT NOT NULL, job_id TEXT NOT NULL,
 lease_token TEXT NOT NULL, lease_generation INTEGER NOT NULL, worker_version TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(epoch_id,lease_generation)
);
CREATE TABLE IF NOT EXISTS serial_pilot_ledger_stage_receipts(
 operation_token TEXT PRIMARY KEY, epoch_id TEXT NOT NULL, spreadsheet_id TEXT NOT NULL, job_id TEXT NOT NULL,
 entity_id TEXT NOT NULL, projection TEXT NOT NULL CHECK(projection IN ('EXPENSE_RAW','DETAIL')),
 source_version INTEGER NOT NULL, source_digest TEXT NOT NULL, source_revision INTEGER NOT NULL,
 sheet_id INTEGER NOT NULL, sheet_name TEXT NOT NULL, before_digest TEXT NOT NULL, payload_digest TEXT NOT NULL,
 ledger_marker TEXT NOT NULL, worker_version TEXT NOT NULL, nonce TEXT NOT NULL,
 notice_algorithm TEXT NOT NULL CHECK(notice_algorithm='SHA256_MALIPANG_NOTICE_POSTIMAGE_V1'),
 notice_postimage_digest TEXT NOT NULL CHECK(length(notice_postimage_digest)=64 AND notice_postimage_digest NOT GLOB '*[^0-9a-f]*'),
 observed_at TEXT NOT NULL, recorded_at TEXT NOT NULL, UNIQUE(epoch_id,entity_id,projection)
);
CREATE TRIGGER IF NOT EXISTS serial_ledger_stage_not_ready BEFORE INSERT ON serial_pilot_ledger_stage_receipts BEGIN SELECT RAISE(ABORT,'ledger stage receipt not ready'); END;
CREATE TRIGGER IF NOT EXISTS serial_ledger_stage_no_replace BEFORE INSERT ON serial_pilot_ledger_stage_receipts WHEN EXISTS(SELECT 1 FROM serial_pilot_ledger_stage_receipts r WHERE r.operation_token=NEW.operation_token OR r.rowid=NEW.rowid OR (r.epoch_id=NEW.epoch_id AND r.entity_id=NEW.entity_id AND r.projection=NEW.projection)) BEGIN SELECT RAISE(ABORT,'ledger stage receipt retained'); END;
CREATE TRIGGER IF NOT EXISTS serial_ledger_stage_no_update BEFORE UPDATE ON serial_pilot_ledger_stage_receipts BEGIN SELECT RAISE(ABORT,'ledger stage receipt immutable'); END;
CREATE TRIGGER IF NOT EXISTS serial_ledger_stage_no_delete BEFORE DELETE ON serial_pilot_ledger_stage_receipts BEGIN SELECT RAISE(ABORT,'ledger stage receipt retained'); END;
CREATE TABLE IF NOT EXISTS serial_pilot_continuation_authorizations(
 operation_token TEXT PRIMARY KEY, epoch_id TEXT NOT NULL,job_id TEXT NOT NULL,lease_token TEXT NOT NULL,
 lease_generation INTEGER NOT NULL,previous_operation_token TEXT NOT NULL,worker_version TEXT NOT NULL,created_at TEXT NOT NULL,
 UNIQUE(epoch_id,lease_generation)
);
