  JOIN stable_recovery_operations o ON o.operation_token=r.operation_token AND o.epoch_id=s.epoch_id AND o.state='VERIFIED' AND o.admitted_at<=r.observed_at
  JOIN stable_source_revision rev ON rev.singleton=1 AND rev.revision=r.source_revision
  JOIN serial_pilot_notice_release_receipts daily_receipt ON daily_receipt.nonce=s.nonce AND daily_receipt.epoch_id=s.epoch_id AND daily_receipt.successor_job_id=s.job_id AND daily_receipt.spreadsheet_id=s.spreadsheet_id AND daily_receipt.source_revision=rev.revision
  JOIN stable_recovery_operations daily_operation ON daily_operation.operation_token=daily_receipt.operation_token AND daily_operation.epoch_id=s.epoch_id AND daily_operation.state='VERIFIED'
  JOIN stable_projection_writes daily ON daily.spreadsheet_id=s.spreadsheet_id AND daily.entity_type='EXPENSE' AND daily.entity_id=j.entity_key AND daily.source_version=j.entity_version AND daily.projection='DAILY' AND daily.operation_token=daily_receipt.operation_token AND daily.source_digest=r.source_digest AND daily.state='VERIFIED'
  JOIN atomic_daily_marker_reservations daily_marker ON daily_marker.spreadsheet_id=daily.spreadsheet_id AND daily_marker.sheet_id=daily.sheet_id AND daily_marker.entity_id=daily.entity_id AND daily_marker.source_version=daily.source_version AND daily_marker.operation_token=daily.operation_token
  JOIN continuous_daily_write_evidence daily_evidence ON daily_evidence.spreadsheet_id=daily.spreadsheet_id AND daily_evidence.entity_id=daily.entity_id AND daily_evidence.sheet_id=daily.sheet_id AND daily_evidence.sheet_name=daily.sheet_name AND daily_evidence.source_version=daily.source_version AND daily_evidence.source_digest=daily.source_digest AND daily_evidence.operation_token=daily.operation_token AND daily_evidence.marker=daily_marker.marker
  JOIN stable_expense_projection_preimages daily_preimage ON daily_preimage.spreadsheet_id=daily.spreadsheet_id AND daily_preimage.entity_type=daily.entity_type AND daily_preimage.entity_id=daily.entity_id AND daily_preimage.source_version=daily.source_version AND daily_preimage.projection=daily.projection AND daily_preimage.sheet_id=daily.sheet_id AND daily_preimage.sheet_name=daily.sheet_name AND daily_preimage.source_digest=daily.source_digest
  JOIN expense_events source ON source.expense_id=j.entity_key AND source.version=j.entity_version AND source.status='CONFIRMED'
  JOIN stable_projection_writes p ON p.spreadsheet_id=s.spreadsheet_id AND p.entity_type='EXPENSE' AND p.entity_id=r.entity_id AND p.projection=r.projection AND p.sheet_id=r.sheet_id AND p.sheet_name=r.sheet_name AND p.source_version=r.source_version AND p.source_digest=r.source_digest AND p.operation_token=r.operation_token AND p.state='VERIFIED'
  JOIN atomic_daily_marker_reservations m ON m.spreadsheet_id=p.spreadsheet_id AND m.sheet_id=p.sheet_id AND m.entity_id=p.entity_id AND m.source_version=p.source_version AND m.operation_token=p.operation_token
  JOIN continuous_ledger_write_evidence le ON le.spreadsheet_id=p.spreadsheet_id AND le.entity_id=p.entity_id AND le.projection=p.projection AND le.operation_kind='CONFIRM' AND le.sheet_id=p.sheet_id AND le.sheet_name=p.sheet_name AND le.source_version=p.source_version AND le.operation_token=p.operation_token AND le.marker=r.ledger_marker AND le.before_digest=r.before_digest AND le.payload_digest=r.payload_digest
  JOIN stable_expense_projection_preimages pi ON pi.spreadsheet_id=p.spreadsheet_id AND pi.entity_type=p.entity_type AND pi.entity_id=p.entity_id AND pi.source_version=p.source_version AND pi.projection=p.projection AND pi.sheet_id=p.sheet_id AND pi.sheet_name=p.sheet_name AND pi.source_digest=p.source_digest
  JOIN continuous_daily_cutovers cutover ON cutover.spreadsheet_id=s.spreadsheet_id AND cutover.state='ACTIVE'
  JOIN serial_pilot_oracle_fence f ON f.spreadsheet_id=s.spreadsheet_id AND f.fence_digest=s.fence_digest AND f.generation=s.fence_generation
  WHERE r.operation_token=OLD.operation_token AND r.spreadsheet_id=OLD.spreadsheet_id AND r.source_version=j.entity_version AND r.observed_at<=r.recorded_at
   AND ((p.projection='EXPENSE_RAW' AND p.entity_id=j.entity_key AND p.sheet_id=cutover.raw_sheet_id AND p.sheet_name=cutover.raw_sheet_name) OR (p.projection='DETAIL' AND p.sheet_id=cutover.detail_sheet_id AND p.sheet_name=cutover.detail_sheet_name AND EXISTS(SELECT 1 FROM expense_document_items item WHERE item.expense_id=j.entity_key AND p.entity_id=j.entity_key||'|'||item.item_id)))
   AND NOT EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name='serial_ledger_stage_not_ready')
   AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_ledger_stage_no_replace','serial_ledger_stage_no_update','serial_ledger_stage_no_delete'))=3
   AND NOT EXISTS(SELECT 1 FROM serial_pilot_continuation_completions x WHERE x.epoch_id=s.epoch_id)
   AND NOT EXISTS(SELECT 1 FROM serial_pilot_oracle_revocations v WHERE v.spreadsheet_id=f.spreadsheet_id AND v.fence_digest=f.fence_digest AND v.fence_generation=f.generation)
   AND NOT EXISTS(SELECT 1 FROM stable_recovery_operations u WHERE u.epoch_id=s.epoch_id AND u.state='ADMITTED')
   AND NOT EXISTS(SELECT 1 FROM failed_jobs z WHERE z.queue_name='malipang-jobs' AND z.job_key='EXPENSE:'||j.entity_key||':'||j.entity_version AND z.status='OPEN')
   AND NOT EXISTS(SELECT 1 FROM stable_projection_writes pending WHERE pending.spreadsheet_id=s.spreadsheet_id AND pending.entity_type='EXPENSE' AND pending.projection IN ('EXPENSE_RAW','DETAIL') AND (pending.entity_id=j.entity_key OR substr(pending.entity_id,1,length(j.entity_key)+1)=j.entity_key||'|') AND (pending.state<>'VERIFIED' OR NOT EXISTS(SELECT 1 FROM serial_pilot_ledger_stage_receipts proof JOIN stable_recovery_operations verified ON verified.operation_token=proof.operation_token AND verified.epoch_id=proof.epoch_id AND verified.state='VERIFIED' WHERE proof.epoch_id=s.epoch_id AND proof.spreadsheet_id=pending.spreadsheet_id AND proof.operation_token=pending.operation_token AND proof.entity_id=pending.entity_id AND proof.projection=pending.projection AND proof.source_version=pending.source_version AND proof.source_digest=pending.source_digest AND proof.source_revision=rev.revision AND proof.sheet_id=pending.sheet_id AND proof.sheet_name=pending.sheet_name)))
   AND NOT EXISTS(SELECT 1 FROM serial_pilot_ledger_stage_receipts extra WHERE extra.epoch_id=s.epoch_id AND NOT EXISTS(SELECT 1 FROM stable_projection_writes matched JOIN stable_recovery_operations verified ON verified.operation_token=matched.operation_token AND verified.epoch_id=s.epoch_id AND verified.state='VERIFIED' WHERE matched.spreadsheet_id=extra.spreadsheet_id AND matched.operation_token=extra.operation_token AND matched.entity_id=extra.entity_id AND matched.projection=extra.projection AND matched.source_version=extra.source_version AND matched.source_digest=extra.source_digest AND matched.sheet_id=extra.sheet_id AND matched.sheet_name=extra.sheet_name AND matched.state='VERIFIED' AND extra.source_revision=rev.revision)))
)
 BEGIN SELECT RAISE(ABORT,'continuation release not verified'); END;

CREATE TRIGGER IF NOT EXISTS serial_final_release_delete BEFORE DELETE ON stable_workbook_claims WHEN OLD.phase IS 'SERIAL_FINAL_RELEASE' AND NOT EXISTS(
SELECT 1 FROM serial_pilot_final_completions final
  JOIN serial_pilot_continuation_sessions session ON session.epoch_id=final.epoch_id AND session.spreadsheet_id=final.spreadsheet_id AND session.job_id=final.job_id AND session.nonce=final.nonce
  JOIN stable_recovery_operations op ON op.epoch_id=session.epoch_id AND op.operation_token=final.operation_token AND op.state='VERIFIED'
  JOIN stable_recovery_epochs epoch ON epoch.epoch_id=session.epoch_id AND epoch.spreadsheet_id=session.spreadsheet_id AND epoch.state='COMPLETE'
  JOIN serial_pilot_final_receipts receipt ON receipt.operation_token=final.operation_token AND receipt.epoch_id=final.epoch_id AND receipt.spreadsheet_id=final.spreadsheet_id AND receipt.job_id=final.job_id AND receipt.nonce=final.nonce AND receipt.worker_version=final.worker_version AND receipt.provider_digest=final.provider_digest AND receipt.notice_digest=final.notice_digest AND receipt.provider_observed_at=final.provider_observed_at AND receipt.notice_observed_at=final.notice_observed_at
  JOIN stable_source_revision revision ON revision.singleton=1 AND revision.revision=receipt.source_revision
  JOIN serial_pilot_oracle_fence fence ON fence.spreadsheet_id=session.spreadsheet_id AND fence.fence_digest=session.fence_digest AND fence.generation=session.fence_generation
  WHERE final.operation_token=OLD.operation_token AND final.spreadsheet_id=OLD.spreadsheet_id AND OLD.state='HELD' AND OLD.phase='SERIAL_FINAL_RELEASE'
   AND NOT EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name IN ('serial_final_completion_not_ready','serial_continuation_completion_not_ready'))
   AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_final_completion_guard','serial_final_completion_apply','serial_final_completion_no_replace','serial_final_completion_no_update','serial_final_completion_no_delete','serial_final_release_delete','serial_final_completion_integrity'))=7
   AND NOT EXISTS(SELECT 1 FROM serial_pilot_oracle_revocations revoked WHERE revoked.spreadsheet_id=fence.spreadsheet_id AND revoked.fence_digest=fence.fence_digest AND revoked.fence_generation=fence.generation)
   AND NOT EXISTS(SELECT 1 FROM stable_recovery_operations pending WHERE pending.epoch_id=session.epoch_id AND pending.state='ADMITTED')
) BEGIN SELECT RAISE(ABORT,'final release not verified'); END;
